function findMean(array) {
  let sum = 0;
  for (let i=0; i<array.length; i++) {
    sum += array[i];
  }
  return sum/array.length;
}

def add_vector(v1, v2):
    if len(v1) != len(v2):
        raise Exception("Vectors are of different lengths")
    result = []
    for i in range(len(v1)):
        result.append(v1[i] + v2[i])
    return result
